+---
+// The Gramaire landing — a standalone splash page outside Starlight's chrome
+// (like /lab), implementing the Claude Design mock's Landing: a sticky brand
+// topbar, a centered hero, the live "one file · edit the source" grammar →
+// railroad showcase driven by the real engine, three capability tiles, and a
+// footer. The theme toggle shares Starlight's `starlight-theme` key so a choice
+// here carries across to the docs pages.
+import "../styles/custom.css";
+import BrandTopbar from "../components/BrandTopbar.astro";
+import LiveGrammar from "../components/LiveGrammar.astro";
+import { SHOWCASE } from "../lib/demo-grammars.ts";
+
+const base = import.meta.env.BASE_URL;
+---
+
+<!doctype html>
+<html lang="en">
+  <head>
+    <meta charset="utf-8" />
+    <meta name="viewport" content="width=device-width, initial-scale=1" />
+    <link rel="icon" type="image/svg+xml" href={`${base}favicon.svg`} />
+    <title>Gramaire — grammars that render themselves</title>
+    <meta
+      name="description"
+      content="An LR parser generator whose source format is Markdown. A .gram.md file renders on GitHub — prose, railroad diagrams, FIRST/FOLLOW tables — and is the exact input the generator reads."
+    />
+    <script is:inline>
+      // No-flash theme: honour a stored choice, else the OS preference. Shares
+      // Starlight's `starlight-theme` key so the topbar toggle persists to docs.
+      (() => {
+        try {
+          const stored = localStorage.getItem("starlight-theme");
+          const theme =
+            stored === "light" || stored === "dark"
+              ? stored
+              : window.matchMedia("(prefers-color-scheme: dark)").matches
+                ? "dark"
+                : "light";
+          document.documentElement.dataset.theme = theme;
+        } catch (e) {
+          document.documentElement.dataset.theme = "light";
+        }
+      })();
+    </script>
+  </head>
+  <body>
+    <BrandTopbar active="home" />
+
+    <main class="landing">
+      <section class="hero">
+        <span class="eyebrow"
+          >LR parser generator · source format is Markdown</span
